spec.definition:
-- The rivers (or the sea) of the study picked, after "Any".
SELECT __text, __value FROM (
  SELECT 0 AS o, 'Any' AS __text, 'any' AS __value
  UNION ALL
  SELECT DISTINCT 1, river, river FROM 'http://feeds/datasets/edogawa-flood/flood.parquet' WHERE scenario = ${scenario:sqlstring}
) ORDER BY o, __text

